const filePath = path.join(__dirname, 'lib', 'courseData.js');
let data = fs.readFileSync(filePath, 'utf8');

// The file exports courses as an array. We'll append our objects before the last bracket.
let newFields = newModules.map(m => JSON.stringify(m, null, 4)).join(',\n');

// Find the last closing bracket and replace it
data = data.replace(/\];\s*$/, `,\n${newFields}\n];\n`);

fs.writeFileSync(filePath, data);
console.log('Successfully injected comprehensive Area 51 data into courseData.js');
